68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
76	     * domain containing at least one dot, with no whitespace in any part.
77	     */
78	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
79	
80	    /**
81	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
82	     * new owner's id, customer code and registration date.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    /**
87	     * Common street-type abbreviations expanded during address normalization. Keys are the
88	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
89	     * expanded form it is replaced with.
90	     */
91	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
92	        "ST", "STREET",
93	        "RD", "ROAD",
94	        "AVE", "AVENUE");
95	
96	    /**
97	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
98	     * is at capacity and cannot take any more.
99	     */
100	    private static final int CITY_CAPACITY = 50;
101	
102	    /**
103	     * The maximum number of owners that may be registered in a single day. Once this many owners
104	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
105	     * owners can be created that day.
106	     */
107	    private static final int DAILY_OWNER_LIMIT = 100;
108	
109	    /**
110	     * The number of owners that may be registered on a single business day before a response starts
111	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
112	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
113	     * high volume.
114	     */
115	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
116	
117	    /**
118	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
119	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
120	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
121	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
122	     */
123	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
124	        "61", 9,
125	        "1", 10);
126	
127	    private final ClinicService clinicService;
128	
129	    private final OwnerMapper ownerMapper;
130	
131	    private final PetMapper petMapper;
132	
133	    private final VisitMapper visitMapper;
134	
135	    public OwnerRestControllerV1(ClinicService clinicService,
136	                                 OwnerMapper ownerMapper,
137	                                 PetMapper petMapper,
138	                                 VisitMapper visitMapper) {
139	        this.clinicService = clinicService;
140	        this.ownerMapper = ownerMapper;
141	        this.petMapper = petMapper;
142	        this.visitMapper = visitMapper;
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
148	        Collection<Owner> owners;
149	        if (lastName != null) {
150	            owners = this.clinicService.findOwnerByLastName(lastName);
151	        } else {
152	            owners = this.clinicService.findAllOwners();
153	        }
154	        if (owners.isEmpty()) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
