337	    /**
338	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
339	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
340	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
341	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
342	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
343	     *
344	     * @param telephone the raw telephone value submitted by the client
345	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
346	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
347	     *                                     400 response
348	     */
349	    private String normalizeTelephone(String telephone) {
350	        String e164 = toE164(telephone);
351	        if (e164 == null) {
352	            throw new InvalidOwnerFieldsException(List.of("telephone"));
353	        }
354	        return e164;
355	    }
356	
357	    /**
358	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
359	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
360	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
361	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
362	     * and when the supplied country code is one with a known national-number length
363	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
364	     * number must have exactly that many digits.
365	     *
366	     * @param telephone the raw telephone value, possibly {@code null}
367	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
368	     */
369	    private String toE164(String telephone) {
370	        if (telephone == null) {
371	            return null;
372	        }
373	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
374	        boolean hasPlus = cleaned.startsWith("+");
375	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
376	        String nationalSignificant = hasPlus
377	            ? digits
378	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
379	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
380	            return null;
381	        }
382	        if (!hasValidNationalNumberLength(nationalSignificant)) {
383	            return null;
384	        }
385	        return "+" + nationalSignificant;
386	    }
387	
388	    /**
389	     * Checks the national-number length of an E.164 number (country code plus national significant
390	     * digits, no leading {@code '+'}) against the per-country requirement in
391	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
392	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
393	     * country code is not listed carries no per-country length requirement and is accepted.
394	     *
395	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
396	     *                            leading {@code '+'}
397	     * @return {@code true} if the national-number length is correct for the country code, or the
398	     *         country code has no listed requirement; {@code false} otherwise
399	     */
400	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
401	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
402	            .filter(nationalSignificant::startsWith)
403	            .max(Comparator.comparingInt(String::length))
404	            .orElse(null);
405	        if (countryCode == null) {
406	            return true;
407	        }
408	        int nationalLength = nationalSignificant.length() - countryCode.length();
409	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
410	    }
