412	    /**
413	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
414	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
415	     * returned value is that address lower-cased.
416	     *
417	     * @param email the raw email value submitted by the client, or {@code null} if omitted
418	     * @return the lower-cased email, or {@code null} if none was supplied
419	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
420	     *                                     yielding a 400 response
421	     */
422	    private String normalizeEmail(String email) {
423	        if (email == null) {
