451	    /**
452	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
453	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
454	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
455	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
456	     *
457	     * @param city     the owner's city
458	     * @param lastName the owner's last name
459	     * @return the formatted customer code
460	     */
461	    private String generateCustomerCode(String city, String lastName) {
462	        String city3 = first3Letters(city);
463	        String last3 = first3Letters(lastName);
464	        int sequence = countOwnersInCity(city) + 1;
465	        return String.format("%s-%s-%04d", city3, last3, sequence);
466	    }
