468	    /**
469	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
470	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
471	     *
472	     * @param value the value to abbreviate
473	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
474	     */
475	    private String first3Letters(String value) {
476	        String letters = value.replaceAll("[^\\p{L}]", "");
477	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
478	    }
