480	    /**
481	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
482	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
483	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
484	     * has not been saved yet, so it is never included in the count.
485	     *
486	     * @param city the city of the owner being created
487	     * @return the number of existing owners in that city
488	     */
489	    private int countOwnersInCity(String city) {
490	        String normalizedCity = normalizeForComparison(city);
491	        return (int) this.clinicService.findAllOwners().stream()
492	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
493	            .count();
