511	    /**
512	     * Rejects creation of an owner once the given business day has already reached its daily quota
513	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
514	     * being that day — the adjusted business day the owner being created will carry — so the quota
515	     * applies per business day. The owner being created has not been saved yet, so it is never
516	     * included in the count.
517	     *
518	     * @param registrationDate the adjusted business-day registration date of the owner being created
519	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
520	     *                                         carry that registration date, yielding a
521	     *                                         429 Too Many Requests response
522	     */
523	    private void rejectDailyLimitReached(LocalDate registrationDate) {
524	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
525	            throw new DailyOwnerLimitReachedException(registrationDate);
526	        }
