529	    /**
530	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
531	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
532	     *
533	     * @param registrationDate the business day to count owners for
534	     * @return the number of existing owners registered on that day
535	     */
536	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
537	        return this.clinicService.findAllOwners().stream()
538	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
539	            .count();
540	    }
