542	    /**
543	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
544	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
545	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
546	     * otherwise.
547	     *
548	     * @param ownerDto the owner response to flag
549	     */
550	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
551	        LocalDate today = toBusinessDay(LocalDate.now());
552	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
553	    }
