555	    /**
556	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
557	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
558	     * applies to the effective registration date whether it was supplied in the request or defaulted
559	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
560	     * feeds every value derived from it (such as the membership number's year segment and the daily
561	     * create-limit's per-day bucket).
562	     *
563	     * @param date the effective registration date, supplied or defaulted
564	     * @return the same date when it is a weekday, otherwise the next Monday
565	     */
566	    private LocalDate toBusinessDay(LocalDate date) {
567	        LocalDate adjusted = date;
568	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
569	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
570	            adjusted = adjusted.plusDays(1);
571	        }
572	        return adjusted;
573	    }
