575	    /**
576	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
577	     * telephones are converted to E.164 here as well so the comparison is independent of the format
578	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
579	     * ignored rather than matched.
580	     *
581	     * @param telephone the E.164 telephone of the owner being created
582	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
583	     *                                          yielding a 409 Conflict response
584	     */
585	    private void rejectDuplicateTelephone(String telephone) {
586	        boolean inUse = this.clinicService.findAllOwners().stream()
587	            .map(Owner::getTelephone)
588	            .map(this::toE164)
589	            .anyMatch(telephone::equals);
590	        if (inUse) {
