596	     * Rejects creation of an owner whose lower-cased email is already used by any other owner.
597	     * The email has already been normalized to its lower-cased form, and stored emails are
598	     * lower-cased here as well, so the comparison is case-insensitive. An owner being created
599	     * without an email ({@code null}) is never a duplicate, and stored owners without an email
600	     * are ignored rather than matched.
601	     *
602	     * @param email the normalized (lower-cased) email of the owner being created, or {@code null}
603	     *              if none was supplied
604	     * @throws DuplicateOwnerEmailException if another owner already uses this email, yielding a
605	     *                                      409 Conflict response
606	     */
607	    private void rejectDuplicateEmail(String email) {
608	        if (email == null) {
609	            return;
