611	        boolean inUse = this.clinicService.findAllOwners().stream()
612	            .map(Owner::getEmail)
613	            .filter(existing -> existing != null)
614	            .map(existing -> existing.toLowerCase(Locale.ROOT))
615	            .anyMatch(email::equals);
616	        if (inUse) {
617	            throw new DuplicateOwnerEmailException(email);
618	        }
