659	    /**
660	     * Enrolls a newly created owner into the household of any existing owner that shares its last
661	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
662	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
663	     * whitespace. When at least one such owner already exists, every member of the household — the
664	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
665	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
666	     * and address is created and back-filled onto the existing members. When no owner yet lives at
667	     * that address under the same last name no identifier is assigned and the owner is created alone.
668	     *
669	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
670	     * @param lastName the last name of the owner being created
671	     * @param address  the address of the owner being created
672	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
673	     */
674	    private String assignHousehold(Owner newOwner, String lastName, String address) {
675	        List<Owner> members = findHouseholdMembers(lastName, address);
676	        if (members.isEmpty()) {
677	            return null;
678	        }
679	        String householdId = members.stream()
680	            .map(Owner::getHouseholdId)
681	            .filter(existing -> existing != null && !existing.isBlank())
682	            .findFirst()
683	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
684	        for (Owner member : members) {
685	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
686	                member.setHouseholdId(householdId);
687	                this.clinicService.saveOwner(member);
688	            }
689	        }
690	        newOwner.setHouseholdId(householdId);
691	        return householdId;
692	    }
693	
694	    /**
695	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
696	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
697	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
698	     * same identifier, so members of one household share a single value.
699	     *
700	     * @param normalizedLastName the household's last name, already normalized for comparison
701	     * @param normalizedAddress  the household's address, already normalized for comparison
702	     * @return the derived household identifier
703	     */
704	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
705	        try {
706	            byte[] digest = MessageDigest.getInstance("SHA-256")
707	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
708	            StringBuilder hex = new StringBuilder(digest.length * 2);
709	            for (byte b : digest) {
710	                hex.append(String.format("%02x", b));
711	            }
712	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
713	        } catch (NoSuchAlgorithmException e) {
714	            throw new IllegalStateException("SHA-256 algorithm not available", e);
715	        }
716	    }
717	
718	    /**
719	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
720	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
721	     * the result is lower-cased.
722	     *
723	     * @param value the value to normalize, possibly {@code null}
724	     * @return the normalized value, or an empty string if {@code value} is {@code null}
725	     */
726	    private String normalizeForComparison(String value) {
727	        if (value == null) {
728	            return "";
729	        }
730	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
731	    }
732	
733	    /**
734	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
735	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
736	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
737	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
738	     * This normalized value is what gets stored and returned, and it is the form every address
739	     * comparison (household duplicate detection and the shared household id) uses.
740	     *
741	     * @param address the raw address value submitted by the client, possibly {@code null}
742	     * @return the normalized address, or an empty string if {@code address} is {@code null}
743	     */
744	    private String normalizeAddress(String address) {
745	        if (address == null) {
746	            return "";
747	        }
748	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
749	        if (collapsed.isEmpty()) {
750	            return collapsed;
751	        }
752	        String[] tokens = collapsed.split(" ");
753	        StringBuilder normalized = new StringBuilder(collapsed.length());
754	        for (int i = 0; i < tokens.length; i++) {
755	            if (i > 0) {
756	                normalized.append(' ');
757	            }
758	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
759	        }
760	        return normalized.toString();
761	    }
762	}
